function validate([root, p, q]) {
  if (!Array.isArray(root) || root.length === 0 || root[0] === null) return 'The tree needs a root.';
  const values = root.filter(v => v !== null);
  if (values.length > 10000) return 'The tree has at most 10^4 nodes.';
  const inRange = v => Number.isInteger(v) && v >= -1000000000 && v <= 1000000000;
  if (!values.every(inRange)) return 'Node values are integers between -10^9 and 10^9.';
  if (new Set(values).size !== values.length) return 'Node values must be unique.';
  if (!inRange(p) || !inRange(q)) return 'p and q are integers between -10^9 and 10^9.';
  if (p === q) return 'p and q must be different.';
  return null;
}

