function lowestCommonAncestor(root, p, q) {
  let found = 0;

  function dfs(node) {
    if (node === null) {
      return null;
    }
    const left = dfs(node.left);
    const right = dfs(node.right);
    if (node === p || node === q) {
      found++;
      return node;
    }
    if (left !== null && right !== null) {
      return node;
    }
    return left !== null ? left : right;
  }

  const answer = dfs(root);
  return found === 2 ? answer : null;
}

