function lowestCommonAncestor(root, p, q) {
  // Record every node's parent with a breadth-first walk.
  const parent = new Map([[root, null]]);
  const queue = [root];
  for (let i = 0; i < queue.length; i++) {
    for (const child of [queue[i].left, queue[i].right]) {
      if (child) { parent.set(child, queue[i]); queue.push(child); }
    }
  }
  if (!parent.has(p) || !parent.has(q)) return null;
  // Mark all ancestors of p (itself included), then climb from q to the first marked node.
  const above = new Set();
  for (let node = p; node; node = parent.get(node)) above.add(node);
  let node = q;
  while (!above.has(node)) node = parent.get(node);
  return node;
}

